#if APP_TESTS
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
namespace FileCompass {
 internal static class ImageBatchTests {
  static void Make(string path,int width,int height,double dpi=96){byte[] pixels=Enumerable.Repeat((byte)180,width*height*4).ToArray();for(int i=3;i<pixels.Length;i+=4)pixels[i]=255;var image=BitmapSource.Create(width,height,dpi,dpi,PixelFormats.Bgra32,null,pixels,width*4);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var output=File.Create(path))encoder.Save(output);}
  static int[] Size(string path){using(var input=File.OpenRead(path)){var frame=BitmapDecoder.Create(input,BitmapCreateOptions.None,BitmapCacheOption.OnLoad).Frames[0];return new[]{frame.PixelWidth,frame.PixelHeight};}}
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MainWindow main=null;Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);checks.Add(label);};Action<Action,string> reject=(action,label)=>{bool rejected=false;try{action();}catch(IOException){rejected=true;}check(rejected,label);};
   try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));FluentTheme.Ensure();AdvancedToolsTests.TestImages(root,check);
    string source=Directory.CreateDirectory(Path.Combine(root,"batch-source")).FullName;string landscape=Path.Combine(source,"landscape.png"),portrait=Path.Combine(source,"portrait.png"),odd=Path.Combine(source,"odd.png");Make(landscape,32,16);Make(portrait,16,32);Make(odd,101,51,300);string original=FileParts.Hash(landscape,CancellationToken.None);
    foreach(int mode in new[]{3,4,5}){string output=Directory.CreateDirectory(Path.Combine(root,"mode-"+mode)).FullName;var options=new ImageToolOptions{OutputFolder=output,Format="PNG",ResizeMode=mode,Width=24,Height=20};ImageTools.Process(new[]{landscape,portrait},options,CancellationToken.None,null);var a=Size(ImageTools.Output(landscape,options));var b=Size(ImageTools.Output(portrait,options));check(mode==3?a.SequenceEqual(new[]{24,20})&&b.SequenceEqual(new[]{24,20}):mode==4?a.SequenceEqual(new[]{24,12})&&b.SequenceEqual(new[]{24,48}):a.SequenceEqual(new[]{40,20})&&b.SequenceEqual(new[]{10,20}),"Batch resize uses correct independent landscape/portrait dimensions for mode "+mode);}
    check(FileParts.Hash(landscape,CancellationToken.None)==original,"Batch resizing preserves original image bytes");
    var rotated=new ImageToolOptions{ResizeMode=4,Width=24,Rotation=90,OutputFolder=Directory.CreateDirectory(Path.Combine(root,"rotated-width")).FullName};ImageTools.Process(new[]{landscape},rotated,CancellationToken.None,null);check(Size(ImageTools.Output(landscape,rotated)).SequenceEqual(new[]{24,48}),"Width-only aspect ratio is calculated after rotation");
    var rounded=new ImageToolOptions{ResizeMode=4,Width=7,OutputFolder=Directory.CreateDirectory(Path.Combine(root,"rounded")).FullName};ImageTools.Process(new[]{odd},rounded,CancellationToken.None,null);check(Size(ImageTools.Output(odd,rounded)).SequenceEqual(new[]{7,4}),"Odd dimensions and non-96 DPI round to exact output pixels");
    reject(()=>ImageTools.Plan(new[]{portrait},new ImageToolOptions{ResizeMode=4,Width=0,OutputFolder=root}),"Zero fixed width is rejected before processing");reject(()=>ImageTools.Dimensions(32,16,new ImageToolOptions{ResizeMode=3,Width=32768,Height=32768}),"Excessive output pixel budgets are rejected before allocation");reject(()=>ImageTools.Dimensions(16,32,new ImageToolOptions{ResizeMode=4,Width=32768}),"Aspect ratio cannot produce an oversized derived dimension");
    reject(()=>ImageTools.Plan(new[]{landscape,portrait},new ImageToolOptions{ResizeMode=3,Width=24,Height=20,OutputFolder=Path.Combine(root,"mode-3")}),"A batch cannot overwrite existing edited images");
    string folder=Directory.CreateDirectory(Path.Combine(root,"Česká složka")).FullName,file=Path.Combine(folder,"original.txt");File.WriteAllText(file,"content");File.SetCreationTime(file,new DateTime(2001,2,3,4,5,6));File.SetLastWriteTime(file,new DateTime(2007,8,9,10,11,12));File.SetLastAccessTime(file,new DateTime(2013,4,5,6,7,8));
    var row=BatchRenameEngine.Preview(new[]{file},new RenameOptions{Name="[File.Created]_[File.CreatedTime]_[N]"})[0];check(row.NewName=="2001-02-03_04-05-06_original.txt"&&row.Warning==null,"Creation date and time rename ordinary files without media tags");
    row=BatchRenameEngine.Preview(new[]{file},new RenameOptions{Name="[File.Modified:yyyyMMdd_HHmmss]_[File.Size]"})[0];check(row.NewName=="20070809_101112_7.txt","Custom modification timestamp and byte size produce deterministic names");row=BatchRenameEngine.Preview(new[]{file},new RenameOptions{Name="[File.Accessed]_[File.AccessedTime]_[File.Folder]"})[0];check(row.NewName=="2013-04-05_06-07-08_Česká složka.txt","Access timestamps and Unicode parent folder names are available");
    row=BatchRenameEngine.Preview(new[]{file},new RenameOptions{Name="[File.Created:yyyy/MM/dd]"})[0];check(row.NewName=="2001_02_03.txt","Date format path separators are sanitized into filename characters");row=BatchRenameEngine.Preview(new[]{file},new RenameOptions{Name="[File.Unknown]"})[0];check(!row.Changed&&row.Warning!=null,"Unknown filesystem fields preserve filenames with an explicit warning");row=BatchRenameEngine.Preview(new[]{folder},new RenameOptions{Name="[File.Size]"})[0];check(!row.Changed&&row.Warning!=null,"Directory sizes are not invented for rename templates");check(!MediaNames.WritableTokens.Contains("[File.Created]"),"Filesystem rename fields do not become writable embedded metadata fields");
    var dialog=new MediaConverterWindow(null,new string[0],source,true,delegate{},delegate{}){Left=-18000,Top=-18000};dialog.resize.SelectedIndex=4;dialog.width.Text="17";dialog.height.Text="ignored";check(dialog.ImageOptions().Width==17&&!dialog.height.IsEnabled,"Width-only converter accepts a width and ignores the derived height field");dialog.resize.SelectedIndex=5;dialog.height.Text="19";check(dialog.ImageOptions().Height==19&&!dialog.width.IsEnabled,"Height-only converter accepts a height and disables width");dialog.resize.SelectedIndex=3;dialog.width.Text="23";dialog.height.Text="31";check(dialog.ImageOptions().Width==23&&dialog.ImageOptions().Height==31,"Converter preserves both exact dimensions");dialog.Show();NavigationTests.Wait(dialog.AnalysisTask);dialog.SettingsTabs.SelectedItem=dialog.GeometryTab;NextStageTests.Draw(dialog,Path.Combine(root,"batch-image-dialog.png"));dialog.Close();
    main=new MainWindow(source){Left=-18000,Top=-18000};main.Show();NavigationTests.WaitPanels(main);main.VerifyImageBatchMenu(check);main.Close();main=null;check(HelpContent.ContextTopic(typeof(MediaConverterWindow))=="media","Image resize dialog has contextual F1 help");File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
   }catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),"FAIL after "+checks.Count+" checks\n"+String.Join("\n",checks)+"\n"+ex);return 1;}finally{if(main!=null)main.Close();}
  }
 }
 public partial class MainWindow {
  internal void VerifyImageBatchMenu(Action<bool,string> check){var group=FluentUiTests.Children<MenuItem>(this).Single(x=>Convert.ToString(x.Header)==L.Text("media.menu"));var titles=group.Items.OfType<MenuItem>().Select(x=>Convert.ToString(x.Header)).ToArray();check(new[]{"action.batchRename","mediaNames.rename","mediaNames.write","media.convertImages","media.convertAudio"}.All(key=>titles.Contains(L.Text(key))),"Batch rename, metadata directions and the unified converter share one submenu");check(FluentUiTests.Children<MenuItem>(this).Count(x=>Convert.ToString(x.Header)==L.Text("imageTools.title"))==0,"Standalone quick-image menu is removed");}
 }
}
#endif
